# connector.py - the generic API handler: runs services we don't own, using their voice map
# (actions/<service>.yaml, generated by the build). An app whose API isn't Wepwawet compliant
# gets a small subclass (connectors/<service>.py) with only its quirks (the API rule, Oct 18).
# Returns the same reply shape as a contract service:
#   {"status": "answered" | "out_of_reach" | ..., "speech": "..."}  or None to pass on.
# A list answer adds "items": [...] and puts {items} in its speech where the list goes;
# the router reads the first read_list_max and asks about the rest.

import contextvars
import importlib.util
import logging
import os
import re

import yaml

log = logging.getLogger("router")
from veil import config, phases  # noqa: E402
import flair  # noqa: E402

_S = config.settings()
HEARD_NEEDS = dict(config.knob(_S, "heard_needs") or {})
_LANG = config.load_yaml(config.path("vocab", "language.yaml")) if os.path.exists(config.path("vocab", "language.yaml")) else {}
NAMING_WORDS = {str(w).lower() for w in (_LANG.get("naming_words") or [])}     # "called", "named"
STRIP_AWAY = {str(w).lower() for w in (_LANG.get("strip_away") or [])}         # "a", "the", "please", "i need"
NOT_ACTION = {str(w).lower() for w in (_LANG.get("not_action_words") or [])}   # "to", "in": never an action's word alone (dump15)
# words that are a date or time by themselves, and the ones that belong to the date after them
WHEN_WORDS = {str(w).lower() for k in ("weekdays", "months", "parts_of_day", "noon_words", "day_words")
              for w in (_LANG.get(k) or [])} | {str(w).lower() for w in (_LANG.get("repeat_words") or {})}
WHEN_LEAD = {str(w).lower() for k in ("every_words", "date_lead") for w in (_LANG.get(k) or [])}
_P0 = config.load_yaml(config.path("vocab", "path0.yaml")) if os.path.exists(config.path("vocab", "path0.yaml")) else {}
FILLER = {str(w).lower() for w in (_P0.get("filler_words") or [])} | flair.persona_words(config.path("personality"))               # spoken needs the router hears itself: {need: person | date}
YOURS_SHARE = float(config.knob(_S, "own_words_share", 0.90))         # your own words in a voice map count this strongly
OBJECT_YIELDS_TO = float(config.knob(_S, "verb_beats_object", 0.85))  # a change verb this sure beats an object noun
NAME_MAX_WORDS = int((_S.get("router") or {}).get("add_name_max_words", 8))   # longer is talk, not a name


def load_yaml(path):
    """The file's settings, or none when it isn't there (an app that takes the words as said has no voice map)."""
    if not os.path.exists(path):
        return {}
    with open(path) as f:
        return yaml.safe_load(f) or {}


def people_words(settings):
    """{a word that names a person: which voice it is}: the voices the voice ID knows, and the
    other names each app's people card gives them (veil/people_map.py)."""
    from veil import lists, people_map
    out = {v.lower(): v for v in people_map.voices(settings)}
    for svc in ((settings or {}).get("services") or {}).values():
        for v, names in people_map.household(settings, lists.people_card(svc)).items():
            for n in names:
                out.setdefault(n, v)
    return out


def verb_pattern(word, stem=False):
    """A verb as a pattern: exactly, or (a user rule's words) each longer word by its stem, so
    "rename" also hears "renamed" and "renaming" (veil/match.py's trimming)."""
    from veil import match
    parts = [re.escape(match.stem(w)) + r"\w*" if stem and len(w) > 3 else re.escape(w) for w in word.split()]
    return r"\b" + r"\s+".join(parts) + r"\b"


def with_voice_map(built, hand):
    """The build's actions (actions/<app>.yaml) with the voice map you edit laid on top, so what you
    save counts after a restart, no build needed: its actions are the ones that can be spoken, each
    calls the command and names the objects the voice map says, and your words count as your own
    (basis yours). The build adds only what it learned from the datasets (basis measured)."""
    import copy
    out = copy.deepcopy(built or {})
    acts = out.get("actions") or {}
    mine = (hand or {}).get("actions") or {}
    if not mine:
        return out
    merged = {}
    for name, a in mine.items():
        a = a or {}
        b = dict(acts.get(name) or {})
        b["api"] = a.get("api") or b.get("api", "")
        if "objects" in a:
            b["objects"] = [str(o).lower() for o in (a.get("objects") or [])]
        verbs = {w: v for w, v in (b.get("verbs") or {}).items() if (v or {}).get("basis") == "measured"}
        for w in a.get("words") or []:
            w = str(w).lower()
            if w and w not in verbs:
                verbs[w] = {"share": ((b.get("verbs") or {}).get(w) or {}).get("share"), "basis": "yours"}
        b["verbs"] = verbs
        merged[name] = b
    out["actions"] = merged
    return out


class AppError(RuntimeError):
    """An app's refusal: what it said, its HTTP status, and how long it asked us to wait (Retry-After, seconds)."""

    def __init__(self, text, status=None, retry_after=None):
        super().__init__(text)
        self.status = status
        try:
            self.retry_after = float(retry_after) if retry_after not in (None, "") else None
        except ValueError:
            self.retry_after = None


class Connector:

    def __init__(self, name, svc, settings, say, actions_dir="/app/actions",
                 connectors_dir="/app/connectors", has_line=None):
        self.name = name
        self.map = load_yaml(os.path.join(actions_dir, f"{name}.yaml"))
        hand = load_yaml(os.path.join(connectors_dir, f"{name}.yaml"))
        self.map = with_voice_map(self.map, hand)
        self.default_action = hand.get("default_action", "list")
        # spoken needs come from the hand-written voice map (the page edits it), so a change is
        # used after a restart, without a build
        self.needs = {a: dict((v or {}).get("needs") or {}) for a, v in (hand.get("actions") or {}).items()}
        self.people = people_words(settings)
        self.has_line = has_line or (lambda section: False)
        self.settings = settings
        self.hand = hand
        # its topic's own words (settings topics: seed and pinned, for the topic this app answers)
        self.topic_words = set()
        for t in (settings.get("topics") or {}).values():
            if (t or {}).get("service") == name:
                for w in list(t.get("seed") or []) + list(t.get("pinned") or []):
                    self.topic_words.add(str(w).lower())
        try:      # the app's commands as read from its spec (the Commands tab): what each requires
            import json
            with open(os.path.join(connectors_dir, f"{name}.commands.json")) as f:
                read = json.load(f)
            from veil import openapi        # a command whose path takes a few values, once per value too (dump8)
            self.commands = {c["api"].upper(): c for c in openapi.expanded(read.get("commands"))}
            self.wepwawet = read.get("wepwawet") or {}         # its x-wepwawet section, as read from its spec
        except (OSError, ValueError):
            self.commands, self.wepwawet = {}, {}
        self.hand_path = os.path.join(connectors_dir, f"{name}.yaml")
        self.rules, self.broken, self.speaker = {}, {}, None
        self.load_rules(hand)
        self.svc, self.say = svc or {}, say
        self.token = config.secret(self.svc.get("secret") or "")      # the vault first, then .env
        mm = hand.get("match_min", (self.svc.get("options") or {}).get("match_min"))     # the voice map's knob
        self.match_min = float(mm) if mm is not None else None
        self.sound_alike = bool(hand.get("sound_alike"))       # "by single hole faucet" for "Buy single whole faucet": asks
        self.ask_min = float(hand["ask_min"]) if hand.get("ask_min") is not None else None   # "spray the wheat": asks
        if self.match_min is None and hand.get("actions"):
            log.info("  ! %s: no match_min (its Voice map tab): no spoken thing matches until it's set", name)
        # its words (the voice map's language:) and the weekdays (vocab/language.yaml): no word lists in the code
        import fields as F
        words = hand.get("language") or {}
        self.weekdays = list(F.WEEKDAYS)
        self.stop = {str(w) for w in words.get("never_in_names") or []} | set(self.weekdays)   # never part of a name
        self.group_plain = {str(w) for w in words.get("project_plain") or []}     # not part of a group's name
        self.me_words = {str(w) for w in words.get("me_words") or []}
        self.undo_what = {str(k): str(v) for k, v in (words.get("undo_names") or {}).items()}
        # same meaning ("our lady" = "mary") and the words that never decide alone ("mary"): veil/match.py
        self.alike = {" ".join(str(k).lower().split()): " ".join(str(v).lower().split())
                      for k, v in (words.get("alike") or {}).items() if str(k).strip() and str(v).strip()}
        self.nearby = [" ".join(str(w).lower().split()) for w in words.get("nearby") or [] if str(w).strip()]
        self.not_said = [str(w).strip() for w in words.get("not_said") or [] if str(w).strip()]   # left out when read (dump12)
        # abbreviations speech-to-text writes, tried when what was heard matches nothing (vocab/language.yaml)
        self.abbrev = {str(k).lower(): [str(x).lower() for x in (v if isinstance(v, list) else [v])]
                       for k, v in (_LANG.get("abbreviations") or {}).items()}
        self.cache = {"items": [], "people": {}, "groups": {}}
        # who spoke and a thing picked by her question, for this request (set by handle)
        self.SPEAKER = contextvars.ContextVar(f"{name}_speaker", default=None)
        self.CHOSEN = contextvars.ContextVar(f"{name}_chosen", default=None)

    def load_rules(self, hand):
        """The user rules (its User rules tab), spoken like an action and run by veil/rules.py. Each is
        checked first (its steps, their settings, the app's commands): a broken one isn't used."""
        from veil import rules
        acts = self.map.setdefault("actions", {})
        for n in self.rules:
            acts.pop(n, None)
        self.rules, self.broken = {}, {}
        for n, r in (hand.get("rules") or {}).items():
            if not isinstance(r, dict):
                continue
            wrong = rules.check(r, set(self.commands) if self.commands else None)
            if wrong:
                self.broken[str(n)] = wrong
                log.info("  ! %s rule %s isn't used: %s", self.name, n, wrong)
                continue
            self.rules[str(n)] = r
            # its words heard by their stems; its objects (a project), when it has any, must be heard too
            objects = [str(o).lower() for o in r.get("objects") or []]
            # its words, and its Search's on_last openings ("call it ..."), each heard as the rule's
            opens = list(r.get("words") or []) + [w for k, st in map(rules.kind_of, r.get("steps") or []) if k == "search"
                                                  for w in rules.param("search", st, "on_last") or []]
            acts[str(n)] = {"api": rules.first_change(r), "objects": objects, "needs_object": bool(objects),
                            "verbs": {str(w).lower(): {"share": None, "basis": "yours", "stem": True} for w in opens}}
        try:
            self.rules_mtime = os.stat(self.hand_path).st_mtime
        except OSError:
            self.rules_mtime = None

    def fresh_rules(self):
        """Saved on the User rules tab: used at once, no restart (one stat per request)."""
        try:
            m = os.stat(self.hand_path).st_mtime
        except OSError:
            return
        if m != self.rules_mtime:
            self.hand["rules"] = load_yaml(self.hand_path).get("rules") or {}
            self.load_rules(self.hand)
            log.info("  %s: user rules read again (%d)", self.name, len(self.rules))

    def changes(self, action):
        """Does this action change something in the app (anything but a GET)?"""
        api = ((self.map.get("actions") or {}).get(action) or {}).get("api", "")
        return bool(api) and not api.upper().startswith("GET ")

    def pick_action(self, text, measured_only=False):
        """(action, score, words found): the action whose verbs best match the words.
        An object that belongs to one action ("what PROJECTS do I have") decides it outright,
        unless a confident verb asks for a change ("ADD a task to the house projects")."""
        self.fresh_rules()
        text = text.lower().replace("\u2019", "'")
        scored = self._verbs(text, measured_only)
        best = max(scored, key=lambda x: x[1]) if scored else (None, 0.0, [])
        # The verb that opens the sentence decides among the actions that have it, so a word
        # inside a name can't take over ("PUT change diaper on the list" is an add, not a change).
        words = re.findall(r"[a-z']+", text)
        acts = self.map.get("actions") or {}
        opening = " ".join(words)
        lead = [(len(w.split()), a) for a in scored for w in a[2]
                if re.match(verb_pattern(w, ((acts.get(a[0]) or {}).get("verbs") or {}).get(w, {}).get("stem")), opening)]
        if lead:      # the longest opening wins ("change the name of" over "change"), then the surest
            best = max(lead, key=lambda x: (x[0], x[1][1]))[1]
        for action, a in (self.map.get("actions") or {}).items():
            for obj in (a.get("objects") or []):
                if re.search(r"\b" + re.escape(obj) + r"\b", text):
                    # another action that names the same thing ("create" a "project") and whose own
                    # word was heard wins over the noun alone: the verb decides between them
                    rival = self._names_with_verb(obj, action, scored)
                    if rival:
                        return rival
                    if best[0] and self.changes(best[0]) and best[1] >= OBJECT_YIELDS_TO:
                        return best
                    return action, 1.0, [obj]
        return best

    def noun_after(self, text, objects):
        """Is the app's own noun ("chore") said after the object ("project"), so the object is inside its name?"""
        nouns = {self.noun(), self.noun() + "s"}
        toks = re.findall(r"[a-z']+", text)
        at = [i for i, t in enumerate(toks) if t in objects]
        return bool(at) and any(t in nouns for t in toks[max(at) + 1:])

    def real_verb(self, said, action, found):
        """(action, why): when only strip_away words picked the action ("I NEED you TO find the
        chore" is no add), the sentence's own verb decides: the action that has it, or None when no
        action has it (then the request stays in its tree: settings tree_stays_home). why is None
        when nothing changed."""
        if any(w.lower() not in STRIP_AWAY for f in found for w in f.split()):
            return action, None
        from veil import match, spoken
        verb = spoken.main_verb(said, STRIP_AWAY | FILLER)
        if not verb:
            return action, None
        stem = match.stem(verb)
        # a word of several ("check off") is that action's only when all of it was said
        owners = [(float(v.get("share") or YOURS_SHARE if isinstance(v, dict) else 0), name)
                  for name, a in (self.map.get("actions") or {}).items()
                  for w, v in ((a.get("verbs") or {}).items())
                  if (match.stem(str(w).lower()) == stem if " " not in str(w).strip()
                      else re.search(r"\b" + re.escape(str(w).lower()) + r"\b", said.lower()))
                  and stem in {match.stem(x) for x in str(w).lower().split()}]
        if owners:
            owner = max(owners)[1]
            return owner, None if owner == action else f"its own verb '{verb}' is {owner}'s"
        return None, f"its own verb '{verb}' is none of {self.name}'s actions"

    def never_by_voice(self, said):
        """The word said that the voice map keeps off the voice (never_by_voice: delete, archive...),
        or None: she says it's done on the app's own page, never "staying home"."""
        low = said.lower()
        return next((str(w) for w in self.hand.get("never_by_voice") or []
                     if re.search(r"\b" + re.escape(str(w).lower()) + r"\b", low)), None)

    def rule_opening(self, said):
        """The user rule whose words open what was said ("rename that to ..."), or None: in the
        app's own context (a follow-up) that's enough to mean the rule."""
        from veil import rules
        said = rules.without_correction(said)      # "No, rename it to ...": the correction's own words aren't the rule's
        action, _, found = self.pick_action(said)
        opening = " ".join(re.findall(r"[a-z']+", said.lower().replace("\u2019", "'")))
        if action in self.rules and any(re.match(verb_pattern(w, True), opening) for w in found):
            return action
        return None

    def about_last(self, rule, said):
        """Does what was said mean this user rule on the thing she last named ("rename that to ...",
        "call it ...")? veil/rules.py about_last."""
        from veil import rules
        return rules.about_last(self.rules.get(rule), said, self.drop_words())

    def rule_offers(self):
        """Her offer of each user rule that changes the thing just named ("rename it"), for the
        add's "anything else?": the router's series_offer_rule line with the rule's first word."""
        from veil import rules
        if not self.has_line("series_offer_rule"):
            return []
        out = []
        for name, r in self.rules.items():
            search = next((p for k, p in map(rules.kind_of, r.get("steps") or []) if k == "search"), None)
            if search and rules.param("search", search, "last") and r.get("words") and self.changes(name):
                out.append(self.say("series_offer_rule", word=str(r["words"][0]).lower()))
        return out

    def _names_with_verb(self, obj, owner, scored):
        """The best other action that names obj in its own words ("new project") or nouns, and had
        one of its words (other than obj) heard; or None."""
        out = None
        for action, score, found in scored:
            if action == owner:
                continue
            a = (self.map.get("actions") or {}).get(action) or {}
            names = [str(w) for w in (a.get("verbs") or {})] + [str(o) for o in (a.get("objects") or [])]
            if not any(re.search(r"\b" + re.escape(obj) + r"\b", w) for w in names):
                continue
            if not any(w != obj and obj not in w.split() for w in found):
                continue
            if out is None or score > out[1]:
                out = (action, score, found)
        return out

    def _verbs(self, text, measured_only):
        """[(action, score, words found)] for every action with at least one verb heard."""
        out = []
        for action, a in (self.map.get("actions") or {}).items():
            if a.get("needs_object") and not any(re.search(r"\b" + re.escape(o) + r"\b", text) for o in a["objects"]):
                continue      # a user rule about a project fits only when a project is named
            if a.get("needs_object") and phases.on("dump15") and self.noun_after(text, a["objects"]):
                continue      # "rename the house project chore": the project is in a chore's name (dump15)
            none_mean_it, found = 1.0, []
            for word, v in (a.get("verbs") or {}).items():
                if re.search(verb_pattern(word, v.get("stem")), text):
                    if measured_only and v.get("basis") != "measured":
                        continue      # your own words are a guess; only data can lift confidence
                    share = v.get("share")
                    if v.get("basis") == "yours":
                        share = max(share or 0, YOURS_SHARE)
                    if share:
                        none_mean_it *= (1 - share)
                        found.append(word)
            if found and phases.on("dump15") and all(w in NOT_ACTION for w in found):
                continue      # only little words the datasets counted ("to", "in"): they pick no action alone
            if found:
                out.append((action, 1 - none_mean_it, found))
        return out

    async def handle(self, said, context=(), memory=None, action=None, speaker=None, chosen=None, resume=None,
                     speaker_info=None):
        """speaker: the household key of who spoke, when Oread is sure (SPEAKER: "me" on the people
        card). chosen: the id of the thing her "which one?" or "...? Say yes" settled (CHOSEN).
        resume: a user rule's state after her question was answered (veil/rules.py).
        speaker_info: who spoke, for a rule's Who spoke ({own, nicknames, score, known}; router.speaker_info)."""
        if self.answers():
            return await self.ask(said, context)
        self.speaker = speaker_info
        sets = []
        for var, value in ((self.SPEAKER, speaker), (self.CHOSEN, chosen)):
            sets.append((var, var.set(value)))
        try:
            if resume is not None and action in self.rules:
                reply = await self.run_rule(said, action, resume)
            else:
                reply = await self._handle(said, context, memory, action)
        finally:
            for var, token in sets:
                var.reset(token)
        ask = (reply or {}).get("ask") or {}
        if ask.get("kind") == "thing" and not reply.get("speech"):
            reply["speech"] = self.thing_question(ask)
        return reply

    def thing_question(self, ask):
        """Her question when the words fit more than one of the app's things ("Do you mean Mow the
        lawn in Voice Tech, or Mow Lawn in House?"), or fit one she isn't sure of ("Mow Lawn? Say yes
        and I'll check it off."). Her lines: thing_which, thing_confirm, and the app's confirm_<action>."""
        choices = ask.get("choices") or []
        if ask.get("mode") == "main" and choices and self.has_line("thing_main"):
            # "There are 3 of them. The main one is Saint Joseph, Husband of the Blessed Virgin Mary, a solemnity, in March."
            from veil import rules
            main, w = choices[0], ask.get("weight") or {}
            own = main.get("fields") or {}
            label = own.get(w.get("words")) if w.get("words") else None
            day = next((rules._when(v) for v in own.values() if rules._when(v) is not None), None)
            return self.say("thing_main", count="several" if ask.get("more") else len(choices), name=main["name"],
                            label=f", {str(label).lower()}" if label else "",
                            when=f", in {day.strftime('%B')}" if day is not None else "")
        if ask.get("mode") in ("which", "main"):
            labels = [self.say("thing_in_group", name=c["name"], group=c["group"]) if c.get("group") else c["name"]
                      for c in choices]
            items = labels[0] if len(labels) == 1 else ", ".join(labels[:-1]) + self.say("thing_or") + labels[-1]
            return self.say("thing_which", items=items)
        act = ask.get("action") or ""
        doing = self.say(f"confirm_{act}") if self.has_line(f"confirm_{act}") else self.say("confirm_any")
        return self.say("thing_confirm", name=(choices[0]["name"] if choices else ""), doing=doing)

    def never_words(self):
        """Words that never tell an app's things apart (never_in_names), for reading an answer."""
        return set(self.stop)

    def drop_words(self):
        """Words that are never part of an item's name as said: strip_away (the language's and the
        app's), filler, its topic's words."""
        return STRIP_AWAY | self.strip_away(None) | FILLER | self.topic_words

    def missing_need(self, said, action):
        """The first spoken need marked required for this action that the router hears itself
        (heard_needs) and didn't hear in what was said, or None."""
        import datetime as dt
        import fields as F
        for need, rule in (self.needs.get(action) or {}).items():
            kind = HEARD_NEEDS.get(need)
            if rule != "required" or not kind:
                continue
            W = F.Words(said)
            if kind == "person":
                heard = F.parse_person(W, self.people)
            elif kind == "date":
                heard = F.parse_date(W, dt.date.today()) or F.parse_time(F.Words(said))
            else:
                heard = True             # a kind the router can't hear: the action's own job
            if not heard:
                return need
        return None

    def ask_for(self, need, said, action):
        """Her question for a missing need, kept as a pending question: the answer is added to
        what was said and the action runs again."""
        section = f"need_{need}" if self.has_line(f"need_{need}") else "need"
        return {"status": "answered", "speech": self.say(section, need=need.replace("_", " ")),
                "ask": {"kind": "need", "need": need, "said": said, "action": action}}

    # ---------- an action with no code of its own: run from the voice map and the spec ----------

    def strip_away(self, action):
        """The app's and the action's own strip_away words (connectors/<app>.yaml)."""
        own = (self.hand.get("language") or {}).get("strip_away") or []
        own = list(own) + list((((self.hand.get("actions") or {}).get(action) or {}).get("strip_away")) or [])
        return {str(w).lower() for w in own}

    def spoken_value(self, said, action):
        """What was said for the action's thing ("create a project called Voice Test" -> Voice Test,
        "add a chore, paint the back of the house on Thursday" -> Paint the back of the house), by
        veil/spoken.py: the sentence diagram marks the dates, the people and the app's own nouns;
        the name is the words between the action's words and the first of those. Left off either end:
        strip_away in three layers (the language's, vocab/language.yaml; the app's, its language:;
        the action's, its voice map entry), and the action's own verbs, objects and topic words.
        Longer than router: add_name_max_words, it's no name (empty: she asks for it)."""
        from veil import spoken, lists
        a = (self.map.get("actions") or {}).get(action) or {}
        lead = set(STRIP_AWAY) | self.strip_away(action)
        for w in list((a.get("verbs") or {}).keys()) + list(a.get("objects") or []) + list(self.topic_words):
            lead.update(str(w).lower().split())
        svc = (self.settings.get("services") or {}).get(self.name) or {}
        stop = set(self.topic_words) | {str(k).lower() for k in lists.cards(svc)}
        thing = spoken.thing(said, lead=lead, people=set(self.people), stop_nouns=stop, naming=NAMING_WORDS,
                             filler=FILLER, when_words=WHEN_WORDS, when_lead=WHEN_LEAD)
        if len(thing.split()) > NAME_MAX_WORDS:     # room talk or her own words coming back: she asks instead
            log.info("  %s: '%s' is %d words, longer than add_name_max_words (%d): not a name",
                     self.name, thing, len(thing.split()), NAME_MAX_WORDS)
            return ""
        return thing

    async def run_generic(self, said, action):
        """Call the action's command itself: each field the app's spec requires in the body is filled
        from the spoken need of the same name. One it can't fill, or a command with a path id (which
        thing?), is said honestly and not sent."""
        a = (self.hand.get("actions") or {}).get(action) or {}
        api_ = " ".join(str(a.get("api") or "").split())
        method, _, path = api_.partition(" ")
        cmd = self.commands.get(api_.upper()) or {}
        call = self.api
        if not method or not path:
            log.info("  %s: '%s' has no command to call - passing on", self.name, action)
            return None
        if "{" in path:
            log.info("  %s %s: %s needs to know which one; the generic runner doesn't pick items yet", self.name, action, api_)
            return {"status": "answered", "speech": self.say("generic_cannot", action=action.replace("_", " "))}
        needs = self.needs.get(action) or {}
        body, unfilled = {}, []
        for req in cmd.get("requires") or []:
            kind, _, field = req.partition(": ")
            if kind != "body" or not field:
                continue
            if field in needs:
                value = self.spoken_value(said, action)
                if value:
                    body[field] = value
                    continue
            unfilled.append(field)
        if unfilled:
            log.info("  %s %s: can't fill %s from what was said - not sent", self.name, action, ", ".join(unfilled))
            return {"status": "answered", "speech": self.say("generic_missing", action=action.replace("_", " "),
                                                             fields=", ".join(unfilled))}
        log.info("  %s %s (generic): %s %s", self.name, action, api_, body)
        await call(method.upper(), path, json=body) if body else await call(method.upper(), path)
        await self.refresh()
        what = next(iter(body.values()), action.replace("_", " "))
        section = f"{action}_done" if self.has_line(f"{action}_done") else "generic_done"
        return {"status": "answered", "speech": self.say(section, name=what, action=action.replace("_", " "))}

    async def run_rule(self, said, action, state=None, memory=None):
        """A user rule (its User rules tab), from the start or from where her question left it.
        memory: what she last answered here (the item she last named, for "rename that")."""
        from veil import rules
        try:
            return await rules.run(self, action, said, state, memory)
        except Exception as e:
            # never hand a failed request to Gemini: it would claim a change that didn't happen
            log.info("  ! %s rule %s failed: %s - answering honestly", self.name, action, e)
            busy = getattr(e, "status", None) == 429 and self.has_line("service_busy")
            reply = {"status": "answered", "speech": self.say("service_busy" if busy else "service_error")}
            from veil import phases
            reads = rules.first_change(self.rules.get(action)).strip().upper().startswith("GET ")
            if phases.on("dump9") and reads:      # at its limit or not answering: the next of the same nature may (router.py)
                reply["node_down"] = "busy" if getattr(e, "status", None) == 429 else "not answering"
            return reply

    async def _handle(self, said, context=(), memory=None, action=None):
        s = 1.0
        if not action:
            action, s, words = self.pick_action(said)
            if not action:
                action, words = self.default_action, []
            log.info("  %s action: %s (%.0f%%, %s)", self.name, action, s * 100,
                     ", ".join(words) or "default")
        if action in self.rules:
            return await self.run_rule(said, action, memory=memory)
        fn = getattr(self, "do_" + action, None)
        missing = self.missing_need(said, action)
        if missing:
            log.info("  %s %s: '%s' is a required spoken need and wasn't heard - asking", self.name, action, missing)
            return self.ask_for(missing, said, action)
        if not fn:
            # no code of the app's own for it: the router runs it from the voice map and the spec
            return await self.run_generic(said, action)
        try:
            return await fn(said, list(context), memory or {})
        except Exception as e:
            # never hand a failed request to Gemini: it would claim a change that didn't happen
            log.info("  ! %s %s failed: %s - answering honestly", self.name, action, e)
            return {"status": "answered", "speech": self.say("service_error")}

    # ---------- the generic app: what every app needs (Oct 18, the API rule) ----------
    # An app's subclass (connectors/<name>.py) overrides only the small hooks below where its API
    # isn't Wepwawet compliant: AUTH, FIELDS, address(), unwrap(), and the bodies it wants.

    AUTH = {"in": "header", "name": "Authorization", "prefix": "Bearer "}   # how its key is sent (x-wepwawet: auth:)
    FIELDS = {"id": "id", "name": "name"}     # standard name -> the app's own field (expectation 13)
    FOLLOW_REDIRECTS = False

    def answers(self):
        """Does it take the words as said (expectation 11: x-wepwawet role answers, or kind contract)?"""
        return self.svc.get("kind") == "contract" or self.wepwawet.get("role") == "answers"

    async def ask(self, said, context=()):
        """The words as said, to its one door (x-wepwawet: answers: said, context), with the earlier
        requests; its answer (a status and a sentence) as it gives it."""
        from veil import access
        door = self.wepwawet.get("answers") or {}
        params = [(door.get("said") or "text", said)] + [(door.get("context") or "context", c) for c in context]
        async with access.client(float(self.svc.get("timeout", 8))) as client:
            r = await client.get(self.svc["url"], params=params, headers=self.auth_headers())
        r.raise_for_status()
        return r.json()

    def field(self, std):
        """The app's own field for a standard name (name, when, who, group), or None. Its things' id
        and name: the list card that reads them says (event_key), else the class's."""
        if std in ("id", "name"):
            if not hasattr(self, "_card_fields"):       # read once: the cards and the voice map change on a restart
                cmd = self.items_command()
                card = self.card_for(f"GET {cmd}") if cmd else {}
                self._card_fields = {k: card[k] for k in ("id", "name") if card.get(k)}
            if std in self._card_fields:
                return self._card_fields[std]
        return self.FIELDS.get(std)

    def auth_headers(self):
        a = self.AUTH or {}
        if not self.token or a.get("in", "header") != "header":
            return {}
        return {a.get("name") or "Authorization": f"{a.get('prefix') or ''}{self.token}"}

    def address(self, path):
        """The path as the app answers it (an app that moves its addresses overrides this)."""
        return path

    def own_path(self, path):
        """A command's path without the start its spec gives every path but its address leaves out
        (services: <app>: spec_prefix: /{domain}/v1, the URL / ports tab: Wikipedia's spec is its feed
        service's, served at /api/rest_v1/feed/...), so nothing is left to fill there (dump6)."""
        from veil import phases
        pre = str(self.svc.get("spec_prefix") or "").strip().rstrip("/")
        if not (phases.on("dump6") and pre):
            return path
        pat = "^" + re.sub(r"\\\{\w+\\\}", "[^/]+", re.escape(pre)) + "(?=/|$)"
        return re.sub(pat, "", path, count=1) or "/"

    def unwrap(self, answer):
        """The answer itself, out of any wrapper the app puts around it."""
        return answer

    def values(self):
        """What a command's {names} and its query parameters are filled from: its options (the
        Defaults tab: calendar_id: US) and today's year, month and day (the house's)."""
        import datetime as dt
        t = dt.datetime.now().astimezone()
        out = {"year": t.year, "month": t.month, "day": t.day}
        out.update({k: v for k, v in (self.svc.get("options") or {}).items()
                    if isinstance(v, (str, int, float)) and not isinstance(v, bool)})
        return out

    def date_values(self, command, said):
        """The day said ("What happened on December 7th?") as a command's {year}, {month} and {day},
        each as the app writes it: a month the spec types as a string is its name in small letters
        (december), else its number; an option <part>_as (name, short, number) says otherwise. {} when no
        day was said (today's stay, values())."""
        import datetime as dt
        import fields as F
        from veil import phases
        cmd = self.commands.get(f"GET {command}".upper()) or {}
        # a part the spec gives a pattern is written to fit it (Wikipedia's 10, 01), today's too (dump7)
        pats = (cmd.get("patterns") or {}) if phases.on("dump7") else {}
        today = dt.datetime.now().astimezone().date()
        got = F.parse_date(F.Words(said or ""), today)
        if not got and not pats:
            return {}
        d = dt.date.fromisoformat(got["date"]) if got else today
        types = cmd.get("types") or {}
        opts = self.svc.get("options") or {}

        def month():
            how = str(opts.get("month_as") or ("name" if types.get("month") == "string" and "month" not in pats else "number"))
            first = d.strftime("%B").lower() if how == "name" else d.strftime("%b").lower() if how == "short" else d.month
            return fit("month", [first, d.strftime("%B").lower(), d.strftime("%b").lower(), d.month, f"{d.month:02d}"])

        def fit(part, ways):
            """The first way of writing it that its pattern takes (the first, with none)."""
            if part not in pats:
                return ways[0]
            try:
                return next((w for w in ways if re.fullmatch(pats[part].lstrip("^").rstrip("$"), str(w))), ways[0])
            except re.error:
                return ways[0]
        out = {"year": d.year, "month": month(), "day": fit("day", [d.day, f"{d.day:02d}"])}
        if got:
            out["day_said"] = f"{d.strftime('%B')} {d.day}"      # "December 7"
        return out

    def filled(self, method, path, command=None, more=None):
        """(path, query): the path with its {names} filled from values() (and more), and the query
        parameters its command takes that values() has (year_type: CIVIL). command: the path as
        the spec lists it, when path was filled already."""
        v = dict(self.values(), **(more or {}))
        cmd = self.commands.get(f"{method} {command or path}".upper()) or {}
        from veil import phases
        if phases.on("dump7") and cmd.get("patterns"):      # today's parts as its patterns say (10/09), a rule's alike
            v.update({k: x for k, x in self.date_values(command or path, "").items() if k not in (more or {})})
        path = self.own_path(path)
        out = re.sub(r"\{(\w+)\}", lambda m: str(v[m.group(1)]) if m.group(1) in v else m.group(0), path)
        query = {}
        for p in cmd.get("params") or []:
            where, _, n = str(p).partition(": ")
            if where == "query" and n in v:
                query[n] = v[n]
        return out, query

    async def api(self, method, path, command=None, fill=None, **kw):
        from veil import access
        path, query = self.filled(method, path, command, fill)
        if query:
            kw["params"] = dict(query, **(kw.get("params") or {}))
        async with access.client(float(self.svc.get("timeout", 8))) as client:
            if phases.on("dump16"):       # at most router: app_answer_max_kb read (inbound defense 3)
                r = await access.capped(client, method, self.svc["url"].rstrip("/") + self.address(path), access.most_kb("app_answer_max_kb"),
                                        headers=self.auth_headers(), follow_redirects=self.FOLLOW_REDIRECTS, **kw)
            else:
                r = await client.request(method, self.svc["url"].rstrip("/") + self.address(path),
                                         headers=self.auth_headers(), follow_redirects=self.FOLLOW_REDIRECTS, **kw)
        if r.status_code >= 300:     # keep the app's own explanation for the log (an unfollowed redirect is a failure too)
            raise AppError(f"{self.name.replace('_', ' ').title()} said {r.status_code}: {r.text[:200]}",
                           r.status_code, r.headers.get("retry-after"))
        if not r.content:
            return {}
        return self.unwrap(r.json())

    def items_command(self):
        """The command that lists its things: the default action's (list), when it's a read."""
        api_ = str(((self.hand.get("actions") or {}).get(self.default_action) or {}).get("api") or "")
        return api_.split(" ", 1)[1].strip() if api_.upper().startswith("GET ") else None

    def card_for(self, command):
        """The list card that reads its things with this command (its id, its skips), or {}."""
        from veil import lists
        want = " ".join(str(command or "").split()).upper()
        return next((c for c in lists.cards(self.svc).values() if " ".join(str(c.get("from") or "").split()).upper() == want), {})

    def writes(self):
        """Does it change anything: a voice map action or a user rule calling anything but a GET?"""
        from veil import rules
        apis = [str((v or {}).get("api") or "") for v in (self.hand.get("actions") or {}).values()]
        apis += [rules.first_change(r) for r in self.rules.values()]
        return any(a and not a.strip().upper().startswith("GET ") for a in apis)

    def _kept_file(self):
        from veil import config
        return config.path("state", f"kept_{self.name}.json")

    def _load_kept(self):
        """The copies on hand kept on disk (state/kept_<app>.json), so a restart doesn't spend a call."""
        import json
        try:
            with open(self._kept_file()) as f:
                return {k: (float(v[0]), tuple(v[1])) for k, v in (json.load(f) or {}).items()}
        except (OSError, ValueError, TypeError, IndexError):
            return {}

    def _save_kept(self):
        import json
        try:
            os.makedirs(os.path.dirname(self._kept_file()), exist_ok=True)
            with open(self._kept_file(), "w") as f:
                json.dump({k: [t, list(out)] for k, (t, out) in self._kept.items()}, f)
        except (OSError, TypeError) as e:
            log.info("  ! %s: copy on hand not kept on disk (%s)", self.name, e)

    async def listing(self, path, command=None, fresh=False):
        """(its answer, the list in it) for a GET, as the router uses a list: with {year} in its address,
        this year's and next ("when" looks forward), each thing's next date from today on (or its last,
        when none is still to come), and its card's skips left out (skip: {is_vigil_mass: true}).
        An app that writes nothing is answered from the copy on hand: read once (the first time after a
        start), again once it's older than its cache_refresh_seconds; one that writes is always read
        live (a change is never made on an old copy). fresh: read it now (the refresh loop)."""
        import time
        key = self.filled("GET", path, command)[0]       # the address as called: the refresh's and a rule's alike
        reads_only = not self.writes()
        kept = getattr(self, "_kept", None)
        if kept is None:
            kept = self._kept = self._load_kept() if reads_only else {}
        waits = getattr(self, "_waits", None)
        if waits is None:
            waits = self._waits = {}
        every = float(self.svc.get("cache_refresh_seconds", 60) or 60)
        now = time.time()
        if reads_only and key in kept and (not fresh and now - kept[key][0] < every or now < waits.get(key, 0)):
            return kept[key][1]            # the copy on hand: fresh enough, or the app asked us to wait
        if now < waits.get(key, 0):        # it asked us to wait and there's no copy: not asked again until then
            raise AppError(f"{self.name} asked to wait ({waits[key] - now:.0f} s left)", 429)
        try:
            out = await self._listing(path, command)
        except Exception as e:
            # it refused (429: too many calls) or didn't answer: the last copy, kept, and a wait
            # as long as it said (Retry-After), else its refresh time
            if getattr(e, "status", None) == 429:
                waits[key] = now + (getattr(e, "retry_after", None) or every)
            if reads_only and key in kept:
                wait = getattr(e, "retry_after", None) or every
                waits[key] = now + wait
                log.info("  %s: %s - answering from the copy on hand (%s old), not asking again for %.0f s",
                         self.name, str(e)[:120], f"{(now - kept[key][0]) / 60:.0f} min", wait)
                return kept[key][1]
            raise
        kept[key] = (now, out)
        if reads_only:
            self._save_kept()
        return out

    async def _listing(self, path, command=None):
        from veil import rules
        template = command or path
        answer = await self.api("GET", path, command=command)
        got = rules._as_list(answer)
        if got is None:
            return answer, None
        if phases.on("dump18"):
            got = got + await self.more_pages(answer)
        card = self.card_for(f"GET {template}")
        if "{year}" in template:
            later = rules._as_list(await self.api("GET", template, fill={"year": int(self.values()["year"]) + 1})) or []
            got = rules.upcoming(got + later, card.get("id") or self.field("id"))
        skip = card.get("skip") or {}
        got = [x for x in got if not (isinstance(x, dict) and any(x.get(k) == v for k, v in skip.items()))]
        w = card.get("weight") or {}
        if w.get("field") and w.get("from") is not None:        # only what matters enough (memorials and up)
            got = [x for x in got if not isinstance(x, dict) or self.heavy_enough(x, w)]
        return answer, got

    # ---------- what should be against what is (the collision hook, dump18) ----------
    # A list card may name the app's list of what should be (defined: {from: its command, month: field,
    # day: field}): every thing with its usual day (Liturgical calendar's feasts as defined). Defined but
    # left out of what is (the year's list) is superseded: she says so, and what took its place.

    async def defined(self, command):
        """(the card's defined, its things) for the list read by command, or ({}, [])."""
        from veil import rules
        d = (self.card_for(f"GET {command}") if command else {}).get("defined") or {}
        src = str(d.get("from") or "")
        if not (phases.on("dump18") and src.upper().startswith("GET ")):
            return {}, []
        _, got = await self.listing(src.split(" ", 1)[1].strip())
        return d, [x for x in got or [] if isinstance(x, dict)]

    def usual_day(self, d, thing, today):
        """Its usual day this year (the defined month and day), or None."""
        import datetime as dt
        try:
            return dt.date(today.year, int(thing.get(d.get("month") or "month")), int(thing.get(d.get("day") or "day")))
        except (TypeError, ValueError):
            return None

    async def not_kept(self, command, text, field, never):
        """Her line when what was said is only in the list of what should be ("Saint Francis of Assisi
        is usually October 4, but it isn't kept this year."), or None."""
        import datetime as dt
        import fields as F
        from veil import rules
        d, things = await self.defined(command)
        if not things:
            return None
        found = [c for c in rules.candidates(text, things, field, "", never, alike=self.alike, nearby=self.nearby) if c["exact"] or c["whole"]]
        if len(found) != 1:
            return None
        today = dt.datetime.now().astimezone().date()
        day = self.usual_day(d, found[0]["fields"], today)
        if not day or not self.has_line("not_kept"):
            return None
        return self.say("not_kept", item=found[0]["name"], usual=F.say_date(day, today) if day >= today else f"{day.strftime('%B')} {day.day}")

    async def gives_way(self, command, item):
        """Her note when the thing she found is kept on another day than its usual one this year, still to
        come ("On October 4 this year it gives way to the Twenty-seventh Sunday in Ordinary Time."), or ""."""
        import datetime as dt
        from veil import rules
        d, things = await self.defined(command)
        if not things or not item or not self.has_line("gives_way"):
            return ""
        idf, nf = self.field("id") or "id", self.field("name") or "name"
        own = item.get("fields") or {}
        key = item.get("id") if item.get("id") is not None else own.get(idf)     # a rule's item keeps the app's own fields
        thing = next((t for t in things if key is not None and t.get(idf) == key), None) \
            or next((t for t in things if str(t.get(nf) or "") == str(item.get("name") or "")), None)
        today = dt.datetime.now().astimezone().date()
        usual = self.usual_day(d, thing or {}, today)
        f = rules.date_field([own])
        at = rules._when(own.get(f)) if f else None
        at = at.date() if isinstance(at, dt.datetime) else at
        if not usual or usual < today or at == usual:
            return ""
        _, year = await self.listing(command)
        on = [x for x in year or [] if isinstance(x, dict) and f and (lambda w: (w.date() if isinstance(w, dt.datetime) else w))(rules._when(x.get(f))) == usual]
        if not on:
            return ""
        return " " + self.say("gives_way", usual=f"{usual.strftime('%B')} {usual.day}", other=rules.unsaid(rules._plain(str(on[0].get(nf))), self.not_said))

    def things_on_hand(self):
        """Every thing it has on hand without a call: its list (cache) and the lists in its copies on hand
        (a rule's reads: Liturgical calendar's feasts), for another app to use (dump18)."""
        out = list(self.cache.get("items") or []) if isinstance(self.cache.get("items"), list) else []
        for _, kept in (getattr(self, "_kept", None) or {}).values():
            got = kept[1] if isinstance(kept, (list, tuple)) and len(kept) > 1 else None
            out += [x for x in got or [] if isinstance(x, dict)]
        return out

    async def more_pages(self, answer):
        """The things on its following pages (an answer's next: its address), up to services: <app>:
        pages_max pages in all (1: the first page only, as before), each on the app's own address (dump18)."""
        from veil import rules
        out, most = [], int(self.svc.get("pages_max", 1) or 1)
        base = self.svc["url"].rstrip("/")
        for _ in range(most - 1):
            nxt = answer.get("next") if isinstance(answer, dict) else None
            if not isinstance(nxt, str) or not nxt.startswith(base):
                break
            answer = await self.api("GET", nxt[len(base):] or "/")
            out += rules._as_list(answer) or []
        return out

    @staticmethod
    def weight_of(item, w):
        """A thing's weight as a number to sort by, most important first (smaller is first): the
        card's weight field, a number or a date (soonest first: what's on my list), its direction."""
        from veil import rules
        v = (item or {}).get(w.get("field"))
        when = rules._when(v)
        if when is not None:
            import datetime as dt
            n = when.timestamp() if isinstance(when, dt.datetime) else dt.datetime.combine(when, dt.time()).timestamp()
        elif isinstance(v, (int, float)) and not isinstance(v, bool):
            n = float(v)
        else:
            return float("inf")
        return -n if w.get("higher", True) and when is None else n

    def heavy_enough(self, item, w):
        v = (item or {}).get(w["field"])
        if not isinstance(v, (int, float)) or isinstance(v, bool):
            return True
        return v >= w["from"] if w.get("higher", True) else v <= w["from"]

    def weigh(self, command, choices):
        """(the choices, most important first, and the card's weight) for her "which one?": by the
        list card's weight (grade, higher first), else as they are and None."""
        w = self.card_for(f"GET {command}").get("weight") if command else None
        if not w or not w.get("field"):
            return choices, None
        return sorted(choices, key=lambda c: self.weight_of(c.get("fields") or {}, w)), w

    async def refresh(self):
        """Its things, people and groups, kept on hand so decisions can be made without calling."""
        path = self.items_command()
        if not path:
            return
        answer, got = await self.listing(path, fresh=self.writes())     # one that reads only: its copy, if fresh
        self.cache["items"] = answer if got is None else got
        self.cache["people"] = await self.app_people()
        self.cache["groups"] = await self.group_names()

    def name_of(self, item):
        return str(item.get(self.field("name")) or "").strip()

    # ---------- groups (a project): "what's in the house project?" ----------
    # A group is named when every word of its name (besides the plain words) was said ("house" ->
    # House), or when its noun ("project") was said with the best, unambiguous match.

    def group_in(self, text, groups):
        """(name, id) of the group this text names, or None."""
        from veil import match
        said = {match.stem(w) for w in re.findall(r"[a-z']+", text.lower())}
        f = next((f for f in self.add_fields().values() if f.get("type") == "choice" and f.get("list")), {})
        says_group = bool(said & {match.stem(str(f.get("list") or ""))})      # its card's word ("project")
        scored = []
        for name, gid in (groups or {}).items():
            words = {match.stem(w) for w in re.findall(r"[a-z']+", name.lower())} - self.group_plain
            if not words:
                continue
            hit = len(words & said)
            if hit == len(words) or (says_group and hit):
                scored.append((hit == len(words), hit, name, gid))
        if not scored:
            return None
        scored.sort(reverse=True)
        if len(scored) > 1 and scored[0][:2] == scored[1][:2]:
            return None          # two groups fit equally: name neither
        return scored[0][2], scored[0][3]

    def group_card(self):
        """The list the add's group field fills (connectors/<app>.yaml: fields: <field>: list:)."""
        from veil import lists
        f = next((f for f in self.add_fields().values() if f.get("type") == "choice" and f.get("list")), {})
        return lists.card(self.svc, f.get("list"))

    async def group_names(self):
        """{group name: id}, from the group card's command and fields (the Defaults tab)."""
        from veil import lists
        try:
            return {n: i for i, n in await lists.items(self.api, self.group_card())}
        except Exception:
            return {}

    # ---------- people ----------

    async def app_people(self):
        """{spoken name: (the app's id, display name)}: the app's people and who each is in the house,
        by the settings on its People tab (veil/people_map.py)."""
        from veil import lists, people_map
        card = lists.people_card(self.svc)
        found = await lists.items(self.api, card)
        return people_map.spoken(found, card, people_map.household(self.settings, card))

    # Who "me" is (the people card, the Defaults tab: me:): "default" -> the card's default voice;
    # "speaker" -> whoever Oread is sure spoke, when that voice is one of the app's people (else the default).

    def speaker_person(self, names):
        from veil import lists
        sp = self.SPEAKER.get()
        if sp and str(lists.people_card(self.svc).get("me") or "default").lower() == "speaker":
            return names.get(str(sp).lower())
        return None

    def default_person(self, names):
        from veil import lists
        who = lists.people_card(self.svc).get("default") or ""
        return self.speaker_person(names) or names.get(str(who).lower())

    def who_in(self, text, names):
        words = set(re.findall(r"[a-z']+", text.lower()))
        if "my" in words or "i" in words:
            words.add("me")
        for spoken, person in names.items():           # a name said outright wins ("Beth's chores")
            if spoken in words and spoken not in self.me_words:
                return person
        if words & self.me_words:
            return self.speaker_person(names) or names.get("me") or self.default_person(names)
        return None

    def spoken_name(self, person, names):
        return "you" if person == self.default_person(names) else person[1].title()

    @staticmethod
    def person_by_id(pid, names):
        return next((p for p in names.values() if p[0] == pid), None)

    # ---------- dates ----------

    def when_in(self, text, today):
        """(date, how to say it) for today / tonight / tomorrow / a weekday, else (None, '')."""
        import datetime as dt
        words = set(re.findall(r"[a-z']+", text.lower()))
        if words & {"today", "tonight"}:
            return today, "today"
        if "tomorrow" in words:
            return today + dt.timedelta(days=1), "tomorrow"
        for i, day in enumerate(self.weekdays):
            if day in words:
                return today + dt.timedelta(days=(i - today.weekday()) % 7), day.title()
        return None, ""

    def due_dt(self, item):
        import datetime as dt
        s = item.get(self.field("when")) if self.field("when") else None
        if not s:
            return None
        return dt.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone()

    def due_date(self, item):
        d = self.due_dt(item)
        return d.date() if d else None

    # ---------- finding the thing you mean ----------
    # The matching itself is shared by every app (veil/match.py): sure / confirm / tie / weak / none.

    def meaningful(self, text, ignore=()):
        from veil import match
        return match.words(text, self.stop | {str(i).lower() for i in ignore})

    def as_things(self, items):
        """The app's things for veil/match.py: id, name and its group's name."""
        by_id = {gid: name for name, gid in (self.cache.get("groups") or {}).items()}
        g = self.field("group")
        return [{"id": c.get(self.field("id")), "name": self.name_of(c), "group": by_id.get(c.get(g)) if g else None, "item": c}
                for c in items]

    def find_item(self, text, items, ignore=(), asking=True):
        """(item, why, candidates): why is ok (sure), confirm, tie, weak or none. Only 'ok' acts at once.
        asking: a weak match may be asked about (the voice map's ask_min); off where a guess would
        change what the request is (an add taken for a move)."""
        from veil import match
        found = match.find(text, self.as_things(items), self.stop | {str(i).lower() for i in ignore}, self.match_min,
                           group_first=self.group_card().get("default"), sound_alike=self.sound_alike,
                           alike=self.alike, nearby=self.nearby, abbrev=self.abbrev,
                           ask_min=self.ask_min if asking else None)
        why = {"sure": "ok"}.get(found.how, found.how)
        return (found.thing or {}).get("item"), why, [c.get("item") for c in found.choices]

    def match_followup(self, said):
        """In context (right after this topic): a change verb plus a real thing's name? Returns
        {"action", "why"} or None. Calls nothing."""
        action, s, words = self.pick_action(said)
        if action == "undo":
            return {"action": "undo", "why": "undo the last change"}
        change = self.change_actions()
        if action not in change | {"add"}:
            return None
        item, why, cands = self.find_item(said, self.cache["items"], set(words) | set(self.cache["people"]))
        if why == "ok" or (why == "confirm" and action in change):
            act = "nudge" if action == "add" and "nudge" in change else action     # "remind Beth about X" and X exists
            return {"action": act, "why": f"{act} + {self.noun()} '{self.name_of(item)}'"
                    + (" (not sure: she asks first)" if why == "confirm" else "")}
        if why in ("tie", "nearby") and action in change:
            return {"action": action, "why": f"matches more than one {self.noun()}: "
                    + ", ".join(self.name_of(c) for c in cands)}
        if action in change and self.meaningful(said, set(words) | set(self.cache["people"])):
            # a change verb in this app's conversation, but no such thing: answer honestly here,
            # never hand it to Gemini (which claims changes it can't make)
            return {"action": action, "why": f"change verb, but no {self.noun()} matched: nothing will change"}
        return None

    def change_actions(self):
        """The actions that change one of its things: a command with the thing's {id}, or undo."""
        acts = self.hand.get("actions") or {}
        return {a for a, v in acts.items() if "{id}" in str((v or {}).get("api") or "")} - set(self.rules)

    NOUN = "item"

    def noun(self):
        """What one of its things is called ("chore")."""
        return str(self.hand.get("noun") or self.NOUN)

    def names_thing(self, said):
        """Does this name one of the things the app has (one, or a tie)? Calls nothing."""
        try:
            _, why, _ = self.find_item(said, self.cache["items"], set(self.cache["people"]), asking=False)
        except Exception:
            return False
        return why in ("ok", "tie", "confirm")

    def refine(self, said, action):
        """"Remind Beth about X" when X already exists is a nudge, not an add; "add tomorrow as
        the date for the X chore" with X there is a move (Oct 17: it made a chore "As the date").
        "What's in the house project?" names a group: its things (list), not the groups."""
        import datetime as dt
        acts = self.hand.get("actions") or {}
        if action != self.default_action and (acts.get(action) or {}).get("objects") \
                and self.group_in(said, self.cache["groups"]) and self.default_action in acts:
            return self.default_action
        if action == "add":
            item, why, _ = self.find_item(said, self.cache["items"], set(self.cache["people"]))
            if "move" in acts and self.when_in(said, dt.datetime.now().astimezone().date())[0] \
                    and not re.search(r"\bremind", said.lower()):
                # the words of the add and its fields ("can you ADD tomorrow as the DATE") aren't the thing's
                talk = set(STRIP_AWAY) | set(self.cache["people"]) | {"add", "put", "set"} | {
                    w for f in self.add_fields().values() for x in f.get("words") or [] for w in str(x).lower().split()}
                if self.find_item(said, self.cache["items"], talk, asking=False)[1] in ("ok", "confirm", "tie"):
                    return "move"
            if why == "ok" and "nudge" in acts:
                return "nudge"
        return action

    def thing_choice(self, c):
        t = self.as_things([c])[0]
        return {"id": t["id"], "name": t["name"], "group": t["group"]}

    def position(self, said, memory=None):
        """The id of the thing named by its place in the list she last read here ("mark number 3
        done", "#3", "the third one"), or None. Counted across "Want to hear the rest?"."""
        read = (memory or {}).get("last_list") or {}
        ids = read.get("ids") or []
        if read.get("app") != self.name or not ids:
            return None
        lang = load_yaml(config.path("vocab", "language.yaml"))
        ones, ordinals = lang.get("ones") or {}, lang.get("ordinals") or {}
        lead = {str(w).lower() for w in lang.get("position_words") or []}       # "number"
        toks = re.findall(r"#?[a-z0-9']+", said.lower())
        n = None
        for i, w in enumerate(toks):
            prev = toks[i - 1] if i else ""
            if w.startswith("#") and w[1:].isdigit():
                n = int(w[1:])
            elif w in ordinals:
                n = ordinals[w]
            elif prev in lead and (w.isdigit() or w in ones):
                n = int(w) if w.isdigit() else ones[w]
            elif w.isdigit() and len(toks) <= 4:          # "mark 3 done": a number alone in a short request
                n = int(w)
            if n is not None:
                break
        return ids[n - 1] if n and 1 <= n <= len(ids) else None

    async def target(self, said, action, memory=None):
        """The one thing this request means, or her question, or an honest reply. Read live from
        the app first: a change is never made on a copy that may be out of date."""
        await self.refresh()
        at = self.position(said, memory)
        if at is not None:                           # by its place in the list she read
            item = next((c for c in self.cache["items"] if c.get(self.field("id")) == at), None)
            return (item, None) if item else (None, {"status": "answered", "speech": self.say("no_match")})
        last = (memory or {}).get("last_chore") or {}
        if phases.on("dump15") and last.get("id") is not None and self.points_at_last(said, action):
            # "mark it complete" right after she named one (a find, an add): that one
            item = next((c for c in self.cache["items"] if c.get(self.field("id")) == last["id"]), None)
            if item:
                return item, None
        chosen = self.CHOSEN.get()
        if chosen is not None:                       # picked by her "which one?" or "...? Say yes"
            for c in self.cache["items"]:
                if c.get(self.field("id")) == chosen:
                    return c, None
            return None, {"status": "answered", "speech": self.say("no_match")}
        item, why, cands = self.find_item(said, self.cache["items"], set(self.cache["people"]))
        if why == "ok":
            return item, None
        if why in ("tie", "nearby", "confirm"):
            return None, {"status": "answered", "speech": None,
                          "ask": {"kind": "thing", "mode": "confirm" if why == "confirm" else "which", "action": action,
                                  "said": said, "choices": [self.thing_choice(c) for c in ([item] if why == "confirm" else cands)]}}
        return None, {"status": "answered", "speech": self.say("no_match")}

    def points_at_last(self, said, action):
        """Do the words, without the action's own, only point back ("it", "that", "the one you just added")?"""
        from veil import rules
        verbs = {w for v in ((self.map.get("actions") or {}).get(action) or {}).get("verbs") or {} for w in str(v).split()}
        toks = [t for t in re.findall(r"[a-z']+", said.lower()) if t not in verbs]
        return rules.points_back(toks, self.drop_words() | verbs | NOT_ACTION)

    def changed(self, item, speech, action):
        """A change she made, remembered with which action it was (undo needs to know)."""
        return {"status": "answered", "speech": speech,
                "chore": {"id": item[self.field("id")], "name": self.name_of(item), "action": action}}

    def command(self, action, item=None):
        """(method, path) of the action's command (the voice map), its {id} filled from the item."""
        api_ = " ".join(str(((self.hand.get("actions") or {}).get(action) or {}).get("api") or "").split())
        method, _, path = api_.partition(" ")
        if item is not None:
            path = path.replace("{id}", str(item.get(self.field("id"))))
        return method.upper(), path

    # ---------- reading ----------

    async def do_list(self, said, context, memory=None):
        import datetime as dt
        today = dt.datetime.now().astimezone().date()
        items = await self.api("GET", self.items_command())
        names = await self.app_people()
        who = self.who_in(said, names)
        day, day_word = self.when_in(said, today)
        group = self.group_in(said, self.cache["groups"] or await self.group_names())
        wf, gf = self.field("who"), self.field("group")

        picked, overdue = [], 0
        for c in items:
            if who and wf and c.get(wf) != who[0]:
                continue
            if group and gf and c.get(gf) != group[1]:
                continue
            due = self.due_date(c)
            if day == today:
                if not due or due > today:
                    continue
                overdue += due < today
            elif day and due != day:
                continue
            picked.append((due or dt.date.max, self.name_of(c), c.get(self.field("id"))))
        picked.sort(key=lambda x: (x[0], x[1]))
        names_read = [name for _, name, _ in picked]

        scope = ""
        if who and self.spoken_name(who, names) != "you":
            scope += " for " + self.spoken_name(who, names)
        if group:
            scope += " in " + group[0]
        if day_word:
            scope += " due " + day_word
        if overdue:
            scope += f", including {overdue} overdue"

        count = len(names_read)
        if count == 0:
            return {"status": "answered", "speech": self.say("list_none", scope=scope)}
        noun = self.noun() if count == 1 else self.noun() + "s"
        # the router reads the list: the first read_list_max, then "Want to hear the rest?"
        return {"status": "answered", "items": names_read, "ids": [i for _, _, i in picked],
                "speech": self.say("list_some", count=count, noun=noun, scope=scope, items="{items}")}

    async def do_projects(self, said, context, memory=None):
        method, path = self.command("projects")
        groups = await self.api(method or "GET", path)
        names = [self.name_of(p) for p in groups if self.name_of(p)]
        if not names:
            return {"status": "answered", "speech": self.say("projects_none")}
        return {"status": "answered", "items": names,
                "speech": self.say("projects", count=len(names), items="{items}")}

    # ---------- changing one of its things ----------

    async def change(self, said, action, line, body=None, memory=None, **line_values):
        """Find the thing, call the action's command on it, say its line."""
        item, reply = await self.target(said, action, memory)
        if reply:
            return reply
        method, path = self.command(action, item)
        b = body(item) if callable(body) else body
        await self.api(method, path, json=b) if b is not None else await self.api(method, path)
        await self.refresh()
        return self.changed(item, self.say(line, name=self.name_of(item), **line_values), action)

    async def do_complete(self, said, context, memory=None):
        return await self.change(said, "complete", "done", self.complete_body(), memory)

    async def do_skip(self, said, context, memory=None):
        return await self.change(said, "skip", "skipped", memory=memory)

    def complete_body(self):
        return None

    async def do_move(self, said, context, memory=None):
        import datetime as dt
        item, reply = await self.target(said, "move", memory)
        if reply:
            return reply
        now = dt.datetime.now().astimezone()
        day, day_word = self.when_in(said, now.date())
        if not day:
            return {"status": "answered", "speech": self.say("move_no_day")}
        old = self.due_dt(item)
        at = old.timetz() if old else dt.time(9, 0, tzinfo=now.tzinfo)
        new_due = dt.datetime.combine(day, at).isoformat()
        method, path = self.command("move", item)
        await self.api(method, path, json=await self.move_body(item, new_due))
        await self.refresh()
        return self.changed(item, self.say("moved", name=self.name_of(item), day=day_word), "move")

    async def move_body(self, item, new_due):
        body = {self.field("when"): new_due}
        return await self.with_required(body, "move", item) if phases.on("dump15") else body

    async def with_required(self, body, action, item):
        """The body with every field the action's command requires (its spec: body: updatedAt) that it
        lacks, copied from the item read as it is now: an app that refuses a change made over a newer
        one gets its current stamp (expectation 6, generic since dump15)."""
        method, path = self.command(action, item)
        need = [r.split(": ", 1)[1] for r in (self.commands.get(" ".join((method, self.command(action)[1])).upper()) or {}).get("requires") or []
                if r.startswith("body: ") and r.split(": ", 1)[1] not in body]
        if not need or not self.items_command():
            return body
        fresh = await self.api("GET", f"{self.items_command()}/{item.get(self.field('id'))}")
        fresh = fresh if isinstance(fresh, dict) else {}
        return dict(body, **{f: fresh.get(f, item.get(f)) for f in need})

    async def do_nudge(self, said, context, memory=None):
        item, reply = await self.target(said, "nudge", memory)
        if reply:
            return reply
        method, path = self.command("nudge", item)
        body = self.nudge_body(item)
        await self.api(method, path, json=body) if body is not None else await self.api(method, path)
        names = self.cache["people"] or await self.app_people()
        person = self.person_by_id(item.get(self.field("who")), names) if self.field("who") else None
        who = self.spoken_name(person, names) if person else "them"
        return self.changed(item, self.say("nudged", name=self.name_of(item), who=who), "nudge")

    def nudge_body(self, item):
        return None

    def undo_reverses(self):
        """The changes the app's undo reverses: the voice map's undo: reverses: (none when unset)."""
        undo = (self.hand.get("actions") or {}).get("undo") or {}
        return {str(a) for a in undo.get("reverses") or []}

    def too_late(self, error):
        """Is this the app refusing an undo because it's too late? Its words for it: the voice map's
        undo: too_late: (none when unset)."""
        undo = (self.hand.get("actions") or {}).get("undo") or {}
        return any(str(w) in str(error) for w in undo.get("too_late") or self.TOO_LATE)

    TOO_LATE = ()

    async def do_undo(self, said, context, memory=None):
        last = (memory or {}).get("last_chore")
        if not last:
            return {"status": "answered", "speech": self.say("undo_nothing")}
        if last.get("action") not in self.undo_reverses():
            # the voice map says which changes the app's undo reverses; no workaround of ours - say so honestly
            return {"status": "answered",
                    "speech": self.say("undo_unsupported", what=self.undo_what.get(last.get("action"), "that change"))}
        method, path = self.command("undo", {self.field("id"): last["id"]})
        try:
            await self.api(method, path)
        except RuntimeError as e:
            log.info("  %s: undo %s of %s %s refused: %s", self.name, last.get("action"), self.noun(), last.get("id"), e)
            if self.too_late(e):
                return {"status": "answered", "speech": self.say("undo_too_late")}
            raise
        await self.refresh()
        return {"status": "answered", "speech": self.say("undone", name=last["name"]), "chore": last}

    # ---------- adding one (then the follow-up series adds the extras) ----------
    # The fields and their generic types come from the voice map (add -> fields); fields.py
    # understands the words, series.py runs the conversation. How the app stores them is its own
    # (new_body, extras_body).

    def add_fields(self):
        return (((self.hand.get("actions") or {}).get("add") or {}).get("fields")) or {}

    def opt(self, key):
        """One of its options (the Defaults tab). Nothing in the code stands in for a missing one."""
        return (self.svc.get("options") or {}).get(key)

    def timed_reminder(self, filled):
        """A thing with a due time gets the reminder at that time (the Defaults tab: remind_when_timed),
        unless one was said either way ("don't remind me" keeps it off). Read back like one asked for."""
        if self.opt("remind_when_timed") and filled.get("due_time") and "remind_at_due" not in filled \
                and "remind_at_due" in self.add_fields():
            filled["remind_at_due"] = {"value": True, "say": "remind at due"}
        return filled

    def opening_extras(self, got, now):
        """The extras said in the opening sentence, through the same step as an answer to "anything
        else?" (series.settle: "nag me" takes its default, "at 4:30" alone means today), then the
        reminder at a given time (timed_reminder)."""
        import series
        extra = {k: f for k, f in self.add_fields().items() if f.get("kind") == "extra"}
        return self.timed_reminder(series.settle(extra, {}, {"values": {k: v for k, v in got["values"].items() if k in extra},
                                                             "named": [n for n in got["named"] if n in extra]}, now))

    def new_body(self, name, person, gid, filled, today):
        """The app's body for a new thing (name, who and group by the standard names)."""
        body = {self.field("name"): name}
        if person and self.field("who"):
            body[self.field("who")] = person[0]
        if gid is not None and self.field("group"):
            body[self.field("group")] = gid
        return body

    async def do_add(self, said, context, memory=None):
        """Create the thing from what was said, then hand the router the follow-up series."""
        import datetime as dt
        import fields as F
        import series
        from veil import spoken as sp
        today = dt.datetime.now().astimezone().date()
        low = " ".join(re.findall(r"[a-z']+", said.lower().replace("\u2019", "'")))
        if phases.on("dump15") and any(re.search(r"\b" + re.escape(str(w).lower()) + r"\b", low) for w in _LANG.get("cancel_phrases") or []):
            return {"status": "answered", "speech": self.say("add_cancelled")}     # "... do not save that": nothing added
        names = self.cache["people"] or await self.app_people()
        groups = await self.group_names()
        flds = self.add_fields()
        got = F.parse_answer(said, flds, dt.datetime.now(), people={k: v[1] for k, v in names.items()}, choices=list(groups))
        # the name: the router's own reading (veil/spoken.py: the sentence diagram, the words as
        # said, strip_away in its three layers); nothing left means she asks for it
        name = self.spoken_value(said, "add")
        if not name:
            return {"status": "answered", "speech": self.say("add_need_name"),
                    "ask": {"kind": "add_name", "said": said}}

        filled = self.opening_extras(got, dt.datetime.now())
        who_disp = (got["values"].get("who") or {}).get("person")
        person = next((v for v in names.values() if v[1] == who_disp), None) or self.default_person(names)
        gfield = next((k for k, f in flds.items() if f.get("type") == "choice" and f.get("list")), None)
        grp = (got["values"].get(gfield) or {}).get("choice") if gfield else None
        if grp and not sp.said_outside(said, name, grp):
            grp = None          # "paint the back of the house": the House project wasn't named, only the thing's words
        grp = grp or self.group_card().get("default")
        gid = groups.get(grp) if grp else None
        if gid is None and grp:
            # never guess another group (it used to take the first one the app listed):
            # left out, the app files it under none, and the log says why
            log.info("  ! %s: default %s '%s' isn't there (%s): check its card's default (Defaults)",
                     self.name, gfield, grp, ", ".join(groups))

        body = self.new_body(name[:1].upper() + name[1:], person, gid, filled, today)
        method, path = self.command("add")
        res = await self.api(method, path, json=body)
        cid = res if isinstance(res, int) else (res.get(self.field("id")) if isinstance(res, dict) else None)
        if isinstance(cid, str) and cid.isdigit():
            cid = int(cid)
        await self.refresh()
        if not cid:
            # never claim it was added without the app's id for the new thing
            raise RuntimeError(f"{self.name} didn't return the new {self.noun()}'s id: {str(res)[:120]}")

        who_say = self.spoken_name(person, names) if person else "you"
        shown = f"{name} for {who_say}, in {grp}" if grp else f"{name} for {who_say}"
        line, state = series.start(shown, self.noun(), flds, filled, self.say, more=self.rule_offers())
        reply = {"status": "answered", "speech": line,
                 "chore": {"id": cid, "name": body[self.field("name")], "action": "add"}}
        if state and cid:
            reply["series"] = dict(state, chore_id=cid)
        return reply


def make(name, svc, settings, say, actions_dir="/app/actions", connectors_dir="/app/connectors", has_line=None):
    """The app's connector: its own class (connectors/<name>.py: APP, a subclass of Connector, only
    where its API diverges), else the generic Connector."""
    cls = Connector
    path = os.path.join(connectors_dir, f"{name}.py")
    if os.path.exists(path):
        spec = importlib.util.spec_from_file_location(f"connector_{name}", path)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        cls = getattr(mod, "APP", Connector)
    return cls(name, svc, settings, say, actions_dir=actions_dir, connectors_dir=connectors_dir, has_line=has_line)
